css:
.proforma-header {
    text-align: center;
    border-bottom: 2px solid #333;
    padding-bottom: 15px;
    margin-bottom: 20px;
}
.proforma-title {
    font-size: 16pt;
    font-weight: bold;
    color: #2c3e50;
    text-transform: uppercase;
}
.waybill-box {
    background-color: #f8f9fa;
    padding: 10px;
    border-radius: 5px;
    text-align: center;
    margin-top: 10px;
}
.info-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 20px;
}
.info-table td {
    padding: 10px;
    border: 1px solid #ddd;
    vertical-align: top;
}
.info-table .label {
    font-weight: bold;
    background: #f0f0f0;
    width: 20%;
    text-transform: uppercase;
    font-size: 8pt;
    color: #666;
}
.goods-header {
    background-color: #2c3e50;
    color: white;
    padding: 10px 15px;
    font-weight: bold;
}
.goods-table {
    width: 100%;
    border-collapse: collapse;
}
.goods-table th {
    background: #34495e;
    color: white;
    padding: 10px;
}
.goods-table td {
    padding: 8px;
    border-bottom: 1px solid #ecf0f1;
}
.purpose-header {
    background-color: #27ae60;
    padding: 8px 15px;
    font-weight: bold;
    color: white;
}
.signature-line {
    border-top: 1px solid #333;
    width: 200px;
    margin: 0 auto;
    padding-top: 50px;
}
/* ===== AMB official letterhead (membrete) ===== */
.memo-letterhead-logo { text-align:left; margin:0 0 8px 0; }
.memo-letterhead-logo img { width:100px; height:auto; }
.memo-sign-img-wrap img { width:175px; height:auto; display:block; margin:4px 0; }
.memo-page { position:relative; min-height:9.6in; margin-top:1.0in; }
.memo-band-footer { position:absolute; left:0; right:0; bottom:0; width:100%; }
.memo-band-footer img { width:100%; display:block; }
